package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import android.view.*;import org.json.*;
/** Actual account state; never invents character slots, equipment or companion species. */
final class PlayView extends View {
 interface Host{JSONObject state();void enter();void back();}
 final Host host;final MenuFrame f=new MenuFrame();final ScenePainter painter=new ScenePainter();final MenuArt art;
 PlayView(Context c,Host h){super(c);host=h;art=MenuArt.get(c);setContentDescription("Play character preview. Enter World at bottom right.");}
 protected void onDraw(Canvas c){f.begin(c,this);f.text(c,"< BACK",24,36,18,150);f.text(c,"THE FORSAKEN REALM • BLOOD & IRON",210,36,25,725);JSONObject state=host.state(),you=state.optJSONObject("you"),account=state.optJSONObject("account"),pet=state.optJSONObject("companion");if(you==null||account==null){f.text(c,"Loading character…",40,140,22,800);c.restore();return;}
 f.panel(c,24,75,265,355,false);f.text(c,"ACTIVE CHARACTER",40,110,20,230);f.text(c,account.optString("username",account.optString("id")),40,150,22,230);f.text(c,"Role: "+you.optString("role"),40,192,18,230);f.text(c,"Faction: "+you.optString("faction"),40,228,18,230);f.text(c,"Level: "+you.optInt("level",1),40,264,18,230);f.text(c,"Gold: "+account.optLong("gold"),40,300,18,230);f.text(c,"Health: "+you.optInt("hp"),40,338,18,230);f.text(c,"Saved character retained",40,393,16,230);
 c.save();c.clipRect(300,70,630,430);c.translate(460,340);c.scale(4.1f,4.1f);painter.actor(c,"you:"+you.optString("equippedWeapon"),0,0,0xff66776a,0,false,-1,false,0,you);c.restore();if(pet!=null){c.save();c.translate(554,412);c.scale(1.6f,1.6f);painter.companion(c,pet,0,-1);c.restore();}
 f.panel(c,646,75,290,355,false);f.text(c,"CURRENT EQUIPMENT",662,110,19,255);JSONObject gear=you.optJSONObject("armorSlots"),bag=you.optJSONObject("inventory");int i=0;for(String slot:new String[]{"helmet","chest","gloves","leggings","boots","shield","hands","backpack"}){String id=slot.equals("hands")?you.optString("equippedWeapon"):slot.equals("shield")?(you.optBoolean("equippedShield")?"shield":""):slot.equals("backpack")?you.optString("equippedBackpack"):gear==null?(slot.equals("helmet")?you.optString("equippedHelmet"):slot.equals("chest")?you.optString("equippedArmour"):""):gear.optString(slot);if(id.isEmpty()||id.equals("null")||bag==null||bag.optInt(id)<1)continue;float x=662+i%2*132,y=130+i/2*66;art.item(c,id,x,y,40);f.text(c,art.name(id),x+44,y+24,12,80);i++;}if(i==0)f.text(c,"No equipment worn",662,150,17,255);if(pet!=null)f.text(c,"Companion: "+pet.optString("kind"),662,414,17,255);
 f.panel(c,646,455,290,60,true);f.text(c,"ENTER WORLD",700,493,22,220);f.text(c,"Persistent multiplayer • full loot outside safe towns",24,486,16,590);c.restore();}
 public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()!=MotionEvent.ACTION_UP)return true;float x=f.x(e.getX()),y=f.y(e.getY());if(x<170&&y<60)host.back();else if(x>=646&&x<=936&&y>=455&&y<=515)host.enter();return true;}
}
